         border-radius: 999px;
         background: rgba(79, 107, 255, 0.12);
         color: var(--accent-strong);
         font-size: 0.85rem;
         font-weight: 700;
         letter-spacing: 0.02em;
       }

       .hero-grid {
         display: grid;
         grid-template-columns: minmax(0, 1.4fr) minmax(280px, 0.9fr);
         gap: 24px;
         align-items: center;
       }

       .hero-copy h1 {
         margin: 0 0 14px;
         font-size: clamp(2.2rem, 4vw, 4.2rem);
         line-height: 1.02;
         letter-spacing: -0.04em;
       }

       .hero-copy p {
         margin: 0;
         max-width: 62ch;
         font-size: 1.05rem;
         line-height: 1.7;
         color: var(--muted);
       }

       .hero-card {
         display: grid;
         gap: 12px;
         padding: 24px;
         border: 1px solid var(--border);
         border-radius: var(--radius-lg);
         background: var(--surface-strong);
         box-shadow: 0 18px 34px rgba(39, 53, 92, 0.08);
       }

       .hero-card strong {
         font-size: 1.1rem;
       }

       .hero-card p {
         margin: 0;
         color: var(--muted);
         line-height: 1.6;
       }

       .faq-section {
         margin-top: 28px;
         display: grid;
         gap: 18px;
       }

       .example {
         border: 1px solid var(--border);
         border-radius: var(--radius-lg);
         background: rgba(255, 255, 255, 0.92);
         box-shadow: 0 14px 34px rgba(24, 40, 72, 0.08);
         overflow: clip;
       }

       .question-button {
         width: 100%;
         display: flex;
         align-items: center;
         justify-content: space-between;
         gap: 16px;
         padding: 22px 24px;
         border: 0;
         background: transparent;
         color: var(--text);
         text-align: left;
         font: inherit;
         font-size: 1.05rem;
         font-weight: 700;
         cursor: pointer;
       }

       .question-button:hover {
         background: rgba(79, 107, 255, 0.04);
       }

       .question-button:focus-visible {
         outline: 3px solid #8da0ff;
         outline-offset: -3px;
       }

       .chevron {
         flex: none;
         width: 2.25rem;
         height: 2.25rem;
         display: grid;
         place-items: center;
         border-radius: 999px;
         background: rgba(79, 107, 255, 0.1);
         color: var(--accent-strong);
         transition: transform 0.2s ease, background-color 0.2s ease;
       }

       .question-button[aria-expanded="true"] .chevron {
         transform: rotate(180deg);
         background: rgba(79, 107, 255, 0.18);
       }

       .details {
         padding: 0 24px 24px;
         color: var(--muted);
       }

       .details p {
         margin: 0;
         max-width: 68ch;
         line-height: 1.7;
       }

       .details[hidden] {
         display: none;
       }

       @media (max-width: 760px) {
         .hero-grid {
           grid-template-columns: 1fr;
         }

         .page-shell {
           padding-inline: 16px;
         }

         .question-button,
         .details {
           padding-left: 18px;
           padding-right: 18px;
         }
       }

       @media (forced-colors: active) {
         body {
           background: Canvas;
           color: CanvasText;
         }

         .hero,
         .hero-card,
         .example {
           background: Canvas;
           border-color: ButtonText;
           box-shadow: none;
         }

         .hero-badge,
         .chevron {
           background: Canvas;
           border: 1px solid ButtonText;
           color: ButtonText;
         }

         .skip-link,
         .question-button {
           color: ButtonText;
         }
       }
     </style>
   </head>
